return ['domain'=>'tag-groups','plural-forms'=>'nplurals=1; plural=0;','language'=>'id-ID','project-id-version'=>'Tag Groups 2.1.2','pot-creation-date'=>'2026-06-15T12:41:40+00:00','po-revision-date'=>'2026-06-22 16:17+0000','x-generator'=>'WP-CLI 2.12.0','messages'=>['Tag Groups'=>'Tag-Groups','https://wordpress.org/plugins/tag-groups/'=>'https://wordpress.org/plugins/tag-groups/','Tag Groups allows you to organize your WordPress taxonomy terms and show them in clouds, tabs, accordions, tables, lists and much more.'=>'Tag-Groups memungkinkan Anda untuk mengorganisir istilah taksonomi WordPress Anda dan menampilkannya dalam awan, tab, akordeon, tabel, daftar, dan banyak lagi.','TaxoPress'=>'TaxoPress','https://taxopress.com'=>'https://taxopress.com','Home'=>'Beranda','Taxonomies'=>'Taksonomi','Front End'=>'Front End','Back End'=>'Back End','First Steps'=>'Langkah Pertama','Setup Wizard'=>'Panduan Pengaturan','Settings'=>'Pengaturan','Tag Group Admin'=>'Admin Grup Tag','The term has been removed from all groups.'=>'Istilah telah dihapus dari semua grup.','Edit this item inline'=>'Edit item ini secara langsung','Quick&nbsp;Edit'=>'Edit Cepat','Please <a %s>click here to run the migration routines</a> to make sure we have migrated all tags.'=>'Silakan <a %s>klik di sini untuk menjalankan rutinitas migrasi</a> untuk memastikan kami telah memigrasikan semua tag.','Your settings/groups and your terms have been exported. Please download the resulting files with right-click or ctrl-click:'=>'Pengaturan/grup dan istilah Anda telah diekspor. Silakan unduh file hasilnya dengan klik kanan atau ctrl-klik:','Writing of the exported settings failed.'=>'Penulisan pengaturan yang diekspor gagal.','You do not have permission to download this export file.'=>'Anda tidak memiliki izin untuk mengunduh file ekspor ini.','The export download link is invalid or has expired. Please run the export again.'=>'Tautan unduhan ekspor tidak valid atau telah kedaluwarsa. Silakan jalankan ekspor lagi.','The requested export file has expired. Please run the export again.'=>'File ekspor yang diminta telah kedaluwarsa. Silakan jalankan ekspor lagi.','The groups have been sorted alphabetically.'=>'Grup telah diurutkan secara alfabetis.','The label cannot be empty.'=>'Label tidak boleh kosong.','A tag group with the label \'%s\' already exists, or the label has not changed. Please choose another one or go back.'=>'Sebuah grup tag dengan label \'%s\' sudah ada, atau label belum berubah. Silakan pilih yang lain atau kembali.','A new tag group with the label \'%s\' has been created!'=>'Sebuah grup tag baru dengan label \'%s\' telah dibuat!','A new parent group with the label \'%s\' has been created at the bottom of the table!'=>'Sebuah grup induk baru dengan label \'%s\' telah dibuat di bagian bawah tabel!','A tag group with the label \'%s\' already exists.'=>'Sebuah grup tag dengan label \'%s\' sudah ada.','The tag group with the label \'%s\' has been saved!'=>'Grup tag dengan label \'%s\' telah disimpan!','A tag group with the id %1$s and the label \'%2$s\' has been deleted.'=>'Sebuah grup tag dengan id %1$s dan label \'%2$s\' telah dihapus.','Error uploading the file.'=>'Kesalahan mengunggah file.','Error reading the file.'=>'Kesalahan membaca file.','Error parsing the file.'=>'Kesalahan mengurai file.','date unknown'=>'tanggal tidak diketahui','Your settings and groups have been imported from the file %1$s (created with plugin version %2$s on %3$s).'=>'Pengaturan dan grup Anda telah diimpor dari file %1$s (dibuat dengan versi plugin %2$s pada %3$s).','%d option was added or changed.'=>'%d opsi ditambahkan atau diubah.','Your terms have been imported from the file %1$s (created with plugin version %2$s on %3$s).'=>'Istilah Anda telah diimpor dari file %1$s (dibuat dengan versi plugin %2$s pada %3$s).','We processed %d term.'=>'Kami memproses %d istilah.','We saved %d term.'=>'Kami menyimpan %d istilah.','The group info of %d term was updated.'=>'Info grup dari %d istilah telah diperbarui.','Filters'=>'Filter','Gutenberg'=>'Gutenberg','Multilingual'=>'Multibahasa','Shortcodes'=>'Shortcodes','Themes and Appearance'=>'Tema dan Penampilan','remove'=>'hapus','(recommended)'=>'(disarankan)','keep'=>'pertahankan','use unfiltered_html filter'=>'gunakan filter unfiltered_html','First Aid'=>'Pertolongan Pertama','REST API'=>'REST API','System Information'=>'Informasi Sistem','Debugging'=>'Debugging','Export/Import'=>'Ekspor/Impor','Reset'=>'Reset','Licences'=>'Lisensi','Transients'=>'Transien','Database'=>'Basis Data','Filesystem'=>'Sistem Berkas','WP Object Cache'=>'Cache Objek WP','Your settings have been saved.'=>'Pengaturan Anda telah disimpan.','Your settings has been saved.'=>'Pengaturan Anda telah disimpan.','All groups have been deleted and assignments reset.'=>'Semua grup telah dihapus dan penugasan direset.','The filter on the tags page has been reset to show all tags.'=>'Filter di halaman tag telah direset untuk menampilkan semua tag.','tag groups'=>'kelompok tag','tag cloud'=>'awan tag','group info'=>'info grup','sidebar widget'=>'widget sidebar','accordion'=>'akordeon','tabs'=>'tab','alphabetical'=>'alfabetis','post list'=>'daftar pos','colors'=>'warna','tag description'=>'deskripsi tag','tag filter'=>'filter tag','post filter'=>'filter pos','backup'=>'cadangan','remove plugin'=>'hapus plugin','remove data'=>'hapus data','delete groups'=>'hapus grup','debugging'=>'debugging','PHP Version'=>'Versi PHP','Ajax Test'=>'Tes Ajax','troubleshooting'=>'pemecahan masalah','benchmarks'=>'tolok ukur','speed test'=>'uji kecepatan','error'=>'kesalahan','testing'=>'pengujian','help'=>'bantuan','Tag Groups Pro'=>'Tag Grup Pro','upgrade'=>'perbarui','more groups'=>'lebih banyak grup','posts'=>'pos','filter'=>'filter','animated'=>'beranimasi','searchable'=>'dapat dicari','Info'=>'Info','author'=>'penulis','version'=>'versi','contact'=>'kontak','about'=>'tentang','Licenses'=>'Lisensi','Credits'=>'Kredit','Development News'=>'Berita Pengembangan','blog'=>'blog','updates'=>'pembaruan','getting started'=>'memulai','introduction'=>'pengantar','sample'=>'contoh','migrate'=>'migrasi','problem'=>'masalah','live block preview'=>'prabaca blok langsung','translation'=>'terjemahan','Migrating the term meta'=>'Migrasi istilah meta','Fixing incorrect tag groups'=>'Memperbaiki grup tag yang salah','Fixing incorrect groups in term meta'=>'Memperbaiki grup yang salah dalam meta istilah','Sorting groups in term meta'=>'Mengurutkan grup dalam meta istilah','Checking the tag names'=>'Memeriksa nama tag','Cache'=>'Cache','(1000x read, 100x write)'=>'(1000x dibaca, 100x ditulis)','ineffective'=>'tidak efektif','Start'=>'Mulai','Sample Content'=>'Konten Contoh','Sample Group A'=>'Grup Contoh A','Sample Group B'=>'Grup Contoh B','Sample Group C'=>'Grup Contoh C','First Sample Tag'=>'Tag Contoh Pertama','Second Sample Tag'=>'Tag Sampel Kedua','Third Sample Tag'=>'Tag Sampel Ketiga','Create a draft sample page with Gutenberg blocks.'=>'Buat halaman sampel draf dengan blok Gutenberg.','Create a draft sample page with shortcodes.'=>'Buat halaman sampel draf dengan shortcode.','The plugin %1$s requires WordPress %2$s to function properly.'=>'Plugin %1$s memerlukan WordPress %2$s agar berfungsi dengan baik.','Please upgrade WordPress and then try again.'=>'Silakan tingkatkan WordPress dan coba lagi.','not assigned'=>'tidak ditugaskan','You\'re using Tag Groups Free. The Pro version has more features and support. %1$sUpgrade to Pro%2$s'=>'Anda menggunakan Tag Groups Gratis. Versi Pro memiliki lebih banyak fitur dan dukungan. %1$sUpgrade ke Pro%2$s','Upgrade to Pro'=>'Tingkatkan ke Pro','Upgrade to Tag Groups Pro'=>'Tingkatkan ke Tag Groups Pro','Enhance the power of Tag Groups with the Pro version:'=>'Tingkatkan kekuatan Tag Groups dengan versi Pro:','21 Shortcodes'=>'21 Shortcodes','18 Gutenberg Blocks'=>'18 Blok Gutenberg','Table Tag Cloud'=>'Awan Tag Tabel','Simple Tag Cloud'=>'Awan Tag Sederhana','Shuffle Box'=>'Kotak Acak','Caching'=>'Caching','Multiple Groups Per Tag'=>'Beberapa Grup Per Tag','Tag Cloud Search'=>'Pencarian Awan Tag','Toggle Post Filter'=>'Alihkan Filter Post','Dynamic Post Filter'=>'Filter Pos Dinamis','Post List'=>'Daftar Pos','Tag Meta Box'=>'Kotak Meta Tag','Post Tags in Groups'=>'Tag Pos dalam Grup','Permissions'=>'Izin','Default Groups'=>'Grup Default','WooCommerce Attributes'=>'Atribut WooCommerce','Parent Group Level'=>'Tingkat Grup Induk','Need Tag Groups Support?'=>'Butuh Dukungan Grup Tag?','If you need help or have a new feature request, let us know.'=>'Jika Anda memerlukan bantuan atau memiliki permintaan fitur baru, beri tahu kami.','Request Support'=>'Minta Dukungan','Detailed documentation is also available on the plugin website.'=>'Dokumentasi terperinci juga tersedia di situs web plugin.','View Knowledge Base'=>'Lihat Basis Pengetahuan','The free Tag Groups plugin cannot be active together with Tag Groups Pro.'=>'Plugin Grup Tag gratis tidak dapat aktif bersamaan dengan Tag Groups Pro.','more information'=>'lebih banyak informasi','Edit tag groups'=>'Edit grup tag','Clicking will leave this page without saving.'=>'Mengklik akan meninggalkan halaman ini tanpa menyimpan.','Welcome to %s!'=>'Selamat datang di %s!','The plugin is ready for use. If you need some assistance, we can walk you through the basic steps.'=>'Plugin siap digunakan. Jika Anda memerlukan bantuan, kami dapat memandu Anda melalui langkah-langkah dasar.','Start the Setup Wizard'=>'Mulai Panduan Pengaturan','Or click here if you prefer to do it on your own.'=>'Atau klik di sini jika Anda lebih suka melakukannya sendiri.','Go to the <span class="dashicons dashicons-tag"></span>&nbsp;Tag Groups <a %s>taxonomy settings</a> and <b>select the taxonomy</b> (tag type) of your tags. In most cases just leave the default: Tags (post_tag).'=>'Pergi ke <span class="dashicons dashicons-tag"></span>&nbsp;Pengaturan Grup Tag <a %s>taxonomy settings</a> dan <b>pilih taxonomy</b> (tipe tag) dari tag Anda. Dalam sebagian besar kasus, cukup biarkan default: Tag (post_tag).','Go to the tag groups admin page and <b>create some groups</b>.'=>'Pergi ke halaman admin grup tag dan <b>buat beberapa grup</b>.','You can find these pages listed on your <a %s>Tag Groups home page</a>.'=>'Anda dapat menemukan halaman ini terdaftar di <a %s>halaman beranda Grup Tag</a> Anda.','Go to your tags and <b>assign them to these groups</b>.'=>'Pergi ke tag Anda dan <b>tetapkan mereka ke grup ini</b>.','Filter by tag group'=>'Filter berdasarkan grup tag','%s created this sample page in the Setup Wizard of the <b>Tag Groups</b> plugin. You can safely edit and delete it or keep it for future reference.'=>'%s membuat halaman contoh ini di Setup Wizard dari <b>Tag Groups</b> plugin. Anda bisa dengan aman mengedit dan menghapusnya atau menyimpannya untuk referensi di masa mendatang.','The following shortcodes use a variety of parameters so that you can get an idea of the options. Feel free to generate a new sample page with more features after upgrading the plugin.'=>'Kode pendek berikut menggunakan berbagai parameter sehingga Anda dapat mendapatkan gambaran tentang opsi yang tersedia. Silakan buat halaman contoh baru dengan lebih banyak fitur setelah memperbarui plugin.','Please find links to the documentation in the <a %s>Tag Groups settings</a>.'=>'Silakan temukan tautan ke dokumentasi di <a %s>pengaturan Grup Tag</a>.','Tabbed Tag Cloud'=>'Awan Tag Tabbed','Accordion Tag Cloud'=>'Awan Tag Accordion','Alphabetical Tag Cloud'=>'Awan Tag Alfabetis','Tag List'=>'Daftar Tag','Alphabetical Tag Index'=>'Indeks Tag Alfabetis','The following blocks use a variety of parameters so that you can get an idea of the options. Feel free to generate a new sample page with more features after upgrading the plugin.'=>'Blok berikut menggunakan berbagai parameter sehingga Anda dapat mendapatkan gambaran tentang opsi yang tersedia. Silakan buat halaman contoh baru dengan lebih banyak fitur setelah memperbarui plugin.','This page was created while you had the Gutenberg editor enabled. Therefore the features only display while Gutenberg is active.'=>'Halaman ini dibuat saat Anda mengaktifkan editor Gutenberg. Oleh karena itu, fitur hanya ditampilkan saat Gutenberg aktif.','Display filter on the "Posts" screen.'=>'Tampilkan filter di layar "Pos".','Add a pull-down menu to the filters above the list of posts. If you filter posts by tag groups, then only items will be shown that have tags (terms) in that particular group. This feature can be turned off so that the menu won\'t obstruct your screen if you use a high number of groups. May not work with all taxonomies.'=>'Tambahkan menu tarik-turun ke filter di atas daftar pos. Jika Anda memfilter pos berdasarkan grup tag, maka hanya item yang akan ditampilkan yang memiliki tag (istilah) dalam grup tertentu itu. Fitur ini dapat dimatikan agar menu tidak menghalangi layar Anda jika Anda menggunakan sejumlah grup yang tinggi. Mungkin tidak berfungsi dengan semua taxonomy.','Display filter on the "Tags" screen.'=>'Tampilkan filter di layar "Tag".','Add a filter to the list of tags. Disable it here if it conflicts with other plugins or themes.'=>'Tambahkan filter ke daftar tag. Nonaktifkan di sini jika konflik dengan plugin atau tema lainnya.','Save Settings'=>'Simpan Pengaturan','Gutenberg block preview'=>'prabentuk blok Gutenberg','Some blocks can show an approximate preview in the Gutenberg editor. If you deactivate this option, then all blocks will show a static icon with text.'=>'Beberapa blok dapat menampilkan prabentuk yang kira-kira di editor Gutenberg. Jika Anda menonaktifkan opsi ini, maka semua blok akan menampilkan ikon statis dengan teks.','Keep groups of translations in sync'=>'Jaga agar kelompok terjemahan tetap sinkron','If you activate this option, we try to sync the groups across all language versions of a tag when you save it. Deactivate it to set groups independently.'=>'Jika Anda mengaktifkan opsi ini, kami akan mencoba untuk menyinkronkan kelompok di semua versi bahasa dari sebuah tag saat Anda menyimpannya. Nonaktifkan untuk mengatur kelompok secara independen.','All Tag Groups features are available as Gutenberg blocks. You can also use shortcodes.'=>'Fitur Semua Grup Tag tersedia sebagai blok Gutenberg. Anda juga dapat menggunakan shortcode.','Click on the features for more information.'=>'Klik pada fitur untuk informasi lebih lanjut.','Display the tags in a tabbed tag cloud.'=>'Tampilkan tag dalam awan tag yang terpisah.','Example'=>'Contoh','Parameters'=>'Parameter','Please find the parameters in the <a %s>documentation</a>.'=>'Silakan temukan parameternya di <a %s>dokumentasi</a>.','Accordion'=>'Akordeon','Display the tags in an accordion.'=>'Tampilkan tag dalam akordeon.','Display the tags in lists under tag groups.'=>'Tampilkan tag dalam daftar di bawah kelompok tag.','Display the tags in tabbed tag cloud with first letters as tabs.'=>'Tampilkan tag dalam awan tag yang terpisah dengan huruf pertama sebagai tab.','(Not tested with right-to-left languages.)'=>'(Tidak diuji dengan bahasa dari kanan ke kiri.)','Display the tags in a list with first letters as heading.'=>'Tampilkan tag dalam daftar dengan huruf pertama sebagai judul.','Group Information'=>'Informasi Grup','Display information about tag groups.'=>'Tampilkan informasi tentang kelompok tag.','The function <b>tag_groups_cloud</b> accepts the same parameters as the [tag_groups_cloud] shortcode, except for those that determine tabs and styling.'=>'Fungsi <b>tag_groups_cloud</b> menerima parameter yang sama seperti shortcode [tag_groups_cloud], kecuali untuk yang menentukan tab dan gaya.','By default it returns a string with the html for a tabbed tag cloud.'=>'Secara default, ini mengembalikan string dengan html untuk tag cloud bertab.','If the optional second parameter is set to \'true\', the function returns a multidimensional array containing tag groups and tags.'=>'Jika parameter kedua opsional diatur ke \'true\', fungsi mengembalikan array multidimensi yang berisi grup tag dan tag.','Enable shortcode in sidebar widgets (if not visible anyway).'=>'Aktifkan shortcode di widget sidebar (jika tidak terlihat juga).','Always load shortcode scripts.'=>'Selalu muat skrip shortcode.','Click for more information'=>'Klik untuk informasi lebih lanjut','Turn off to load the scripts only on posts and pages where a shortcode appears.'=>'Matikan untuk memuat skrip hanya pada pos dan halaman di mana shortcode muncul.','Turn on if you use these shortcodes in widgets.'=>'Nyalakan jika Anda menggunakan shortcode ini di widget.','Here you can choose a theme for the Tabbed Tag Cloud and the Accordion Tag Cloud.'=>'Di sini Anda dapat memilih tema untuk Tabbed Tag Cloud dan Accordion Tag Cloud.','New themes can be created with the <a href="http://jqueryui.com/themeroller/" target="_blank">jQuery UI ThemeRoller</a>:'=>'Tema baru dapat dibuat dengan <a href="http://jqueryui.com/themeroller/" target="_blank">jQuery UI ThemeRoller</a>:','On the page "Theme Roller" you can customize all features or pick one set from the gallery. Finish with the "download" button.'=>'Di halaman "Theme Roller" Anda dapat menyesuaikan semua fitur atau memilih satu set dari galeri. Selesaikan dengan tombol "download".','On the next page ("Download Builder") you will need to select the version 1.12.x and the components "Widget", "Accordion" and "Tabs". Make sure that before downloading you enter at the bottom as "CSS Scope" <b>.tag-groups-cloud</b> (including the dot).'=>'Di halaman berikutnya ("Download Builder") Anda perlu memilih versi 1.12.x dan komponen "Widget", "Accordion" dan "Tabs". Pastikan bahwa sebelum mengunduh Anda memasukkan di bagian bawah sebagai "CSS Scope" <b>.tag-groups-cloud</b> (termasuk titik).','Then you unpack the downloaded zip file. You will need the "images" folder and the "jquery-ui.theme.min.css" file.'=>'Kemudian Anda mengekstrak file zip yang diunduh. Anda akan memerlukan folder "images" dan file "jquery-ui.theme.min.css".','Create a new folder inside your <i>wp-content/uploads</i> folder (for example "my-theme") and copy there these two items.'=>'Buat folder baru di dalam folder <i>wp-content/uploads</i> Anda (misalnya "my-theme") dan salin dua item ini ke sana.','Enter the name of this new folder (for example "my-theme") below.'=>'Masukkan nama folder baru ini (misalnya "my-theme") di bawah.','own theme'=>'Tema sendiri','Don\'t load a theme.'=>'Jangan muat tema.','Here you can turn off jQuery UI themes if your WordPress theme brings its own jQuery UI theme, in order to avoid conflicts.'=>'Di sini Anda dapat mematikan tema jQuery UI jika tema WordPress Anda membawa tema jQuery UI sendiri, untuk menghindari konflik.','Further options'=>'Opsi lebih lanjut','Use jQuery.  (Default is on. Other plugins might override this setting.)'=>'Gunakan jQuery. (Default adalah aktif. Plugin lain mungkin menimpa pengaturan ini.)','Tabs triggered by hovering mouse pointer (without clicking).'=>'Tabs yang dipicu dengan mengarahkan pointer mouse (tanpa mengklik).','Collapsible tabs (toggle open/close).'=>'Tab yang dapat dilipat (toggle buka/tutup).','HTML in tag description:'=>'HTML dalam deskripsi tag:','By default the description appears in a tooltip when you hover the mouse over a tag in a tag cloud.'=>'Secara default deskripsi muncul dalam tooltip ketika Anda mengarahkan mouse ke atas tag dalam awan tag.','If you don\'t trust all users of your site, remove the HTML or use a plugin to give the unfiltered_html capability only to users you trust.'=>'Jika Anda tidak mempercayai semua pengguna situs Anda, hapus HTML atau gunakan plugin untuk memberikan kemampuan unfiltered_html hanya kepada pengguna yang Anda percayai.','Save Theme Options'=>'Simpan Opsi Tema','Search for settings'=>'Cari pengaturan','Search for setting pages. Type a space to show all settings.'=>'Cari halaman pengaturan. Ketik spasi untuk menampilkan semua pengaturan.','Search Results'=>'Hasil Pencarian','Nothing found'=>'Tidak ada yang ditemukan','Active Taxonomies'=>'Taxonomies Aktif','Group Statistics'=>'Statistik Grup','for the selected language'=>'untuk bahasa yang dipilih','go to tag group administration'=>'masuk ke administrasi grup tag','Enable Tag Groups Public API Access'=>'Aktifkan Akses API Publik Grup Tag','Enable public access to tag groups endpoint /wp-json/tag-groups/v1/groups/.'=>'Aktifkan akses publik ke endpoint grup tag /wp-json/tag-groups/v1/groups/.','Enable Terms Public API Access'=>'Aktifkan Akses API Publik Istilah','Enable public access to terms endpoint /wp-json/tag-groups/v1/terms/.'=>'Aktifkan akses publik ke endpoint istilah /wp-json/tag-groups/v1/terms/.','Choose the taxonomies for which you want to use Tag Groups:'=>'Pilih taxonomies yang ingin Anda gunakan untuk Tag-Groups:','The default texonomy is <b>Tags (post_tag)</b>. Please note that the tag clouds might not work with all taxonomies and that some taxonomies listed here may not be accessible in the admin backend. If you don\'t understand what is going on here, just leave the default.'=>'Taxonomy default adalah <b>Tags (post_tag)</b>. Harap dicatat bahwa awan tag mungkin tidak berfungsi dengan semua taxonomies dan bahwa beberapa taxonomies yang terdaftar di sini mungkin tidak dapat diakses di backend admin. Jika Anda tidak memahami apa yang terjadi di sini, cukup tinggalkan default.','<b>Please deselect taxonomies that you don\'t use. Using several taxonomies for the same post type or hierarchical taxonomies (like categories) is experimental and not supported.</b>'=>'<b>Silakan hapus centang pada taxonomies yang tidak Anda gunakan. Menggunakan beberapa taxonomies untuk jenis pos yang sama atau taxonomies hierarkis (seperti kategori) adalah eksperimen dan tidak didukung.</b>','To see the post type, hover your mouse over the option.'=>'Untuk melihat post type, arahkan mouse Anda ke opsi tersebut.','If you use a custom taxonomy, make sure that the attribute "Public" is set to "true" and "Hierarchical" to "false".'=>'Jika Anda menggunakan taxonomy kustom, pastikan atribut "Public" diatur ke "true" dan "Hierarchical" ke "false".','Show hierarchical taxonomies. Not all Tag Groups features will work with these taxonomies.'=>'Tampilkan taxonomies hierarkis. Tidak semua fitur Grup Tag akan berfungsi dengan taxonomies ini.','Save Taxonomies'=>'Simpan Taxonomies','Export'=>'Ekspor','Use this button to export all Tag Groups settings and groups and all terms that are assigned to a group into files.'=>'Gunakan tombol ini untuk mengekspor semua pengaturan dan grup Grup Tag serta semua istilah yang ditugaskan ke grup ke dalam file.','You can import both files separately. Category hierarchy won\'t be saved. When you restore terms that were deleted, they receive new IDs and you must assign them to posts again. Exporting cannot substitute a backup.'=>'Anda dapat mengimpor kedua file secara terpisah. Hierarki kategori tidak akan disimpan. Ketika Anda mengembalikan istilah yang telah dihapus, mereka akan menerima ID baru dan Anda harus menugaskan mereka ke post lagi. Mengekspor tidak dapat menggantikan cadangan.','Export Files'=>'Ekspor Berkas','Import'=>'Impor','Below you can import previously exported settings/groups or terms from a file.'=>'Di bawah ini Anda dapat mengimpor pengaturan/grup atau istilah yang telah diekspor sebelumnya dari sebuah file.','It is recommended to back up the database of your site before proceeding.'=>'Disarankan untuk mencadangkan database situs Anda sebelum melanjutkan.','Please import the settings before the terms.'=>'Silakan impor pengaturan sebelum istilah.','Import File'=>'Impor Berkas','Use this button to delete all tag groups and assignments. Your tags will not be changed. Check the checkbox to confirm.'=>'Gunakan tombol ini untuk menghapus semua grup tag dan penugasan. Tag Anda tidak akan diubah. Centang kotak untuk mengonfirmasi.','Please keep in mind that the tag assignments cannot be recovered by the export/import function.'=>'Harap diingat bahwa penugasan tag tidak dapat dipulihkan melalui fungsi ekspor/impor.','I know what I am doing.'=>'Saya tahu apa yang saya lakukan.','Delete Groups'=>'Hapus Grup','Delete Settings and Groups'=>'Hapus Pengaturan dan Grup','Delete all groups and settings when uninstalling the plugin.'=>'Hapus semua grup dan pengaturan saat mencopot plugin.','Debug mode is on.'=>'Mode debug aktif.','Verbose logging is enabled with CM_DEBUG.'=>'Logging verbose diaktifkan dengan CM_DEBUG.','Verbose logging is on.'=>'Logging verbose aktif.','Turn off '=>'Matikan ','Verbose logging is off.'=>'Logging verbose dimatikan.','Turn on'=>'Aktifkan','Debug mode is off.'=>'Mode debug dimatikan.','Learn more <a %s>about debugging</a>.'=>'Pelajari lebih lanjut <a %s>tentang debugging</a>.','Migrate tags to the new format of Tag Groups.'=>'Migrasikan tag ke format baru dari Grup Tag.','The plugin automatically migrates tags to the new format and tries to keep track of changes. There may, however, be cases where other components made unnoticed changes. You might also need to manually migrate tags after you enabled a taxonomy that already contained untracked tags.'=>'Plugin secara otomatis memigrasikan tag ke format baru dan berusaha untuk melacak perubahan. Namun, mungkin ada kasus di mana komponen lain membuat perubahan yang tidak terlihat. Anda mungkin juga perlu memigrasikan tag secara manual setelah Anda mengaktifkan taksonomi yang sudah berisi tag yang tidak terlacak.','Migrate'=>'Migrasi','Running the maintenance can solve issues that you encounter during filtering by tag groups.'=>'Menjalankan pemeliharaan dapat menyelesaikan masalah yang Anda temui selama penyaringan berdasarkan grup tag.','Maintenance'=>'Pemeliharaan','Reset the filter on the tags page to show all tags.'=>'Reset filter di halaman tag untuk menampilkan semua tag.','Use it if a JavaScript error disables the filter menu. Note that it is still recommended to find out the cause of the error.'=>'Gunakan jika kesalahan JavaScript menonaktifkan menu filter. Perhatikan bahwa tetap disarankan untuk mencari tahu penyebab kesalahan tersebut.','Reset Tag Filter'=>'Reset Filter Tag','Please stay on this page until all processes have finished.'=>'Silakan tetap di halaman ini sampai semua proses selesai.','There have been errors.'=>'Telah terjadi kesalahan.','Continue'=>'Lanjutkan','Finished!'=>'Selesai!','The following terms cannot be used:'=>'Istilah berikut tidak dapat digunakan:','Number of processed items: '=>'Jumlah item yang diproses: ','Number of changed items: '=>'Jumlah item yang diubah: ','WordPress Version'=>'Versi WordPress','Site URL'=>'URL Situs','Home URL'=>'URL Beranda','Active Theme'=>'Tema Aktif','Version'=>'Versi','Checking...'=>'Memeriksa...','Show the Response'=>'Tampilkan Respon','passed'=>'lulus','failed'=>'gagal','Benchmarks'=>'Benchmark','Tag groups pro only'=>'Grup tag pro saja','Server'=>'Server','Constants'=>'Konstanta','Well done!'=>'Kerja yang baik!','Now go the Tag Group Administration.'=>'Sekarang pergi ke Administrasi Grup Tag.','Or preview the sample page here.'=>'Atau pratinjau halaman contoh di sini.','Or go to the <a %1$s>Tag Groups settings</a> or visit the <a %2$s>documentation</a>.'=>'Atau pergi ke <a %1$s>pengaturan Tag Groups</a> atau kunjungi <a %2$s>dokumentasi</a>.','Now go to the <a %1$s>Tag Groups settings</a>, or visit the <a %2$s>documentation</a>.'=>'Sekarang pergi ke <a %1$s>pengaturan Tag Groups</a>, atau kunjungi <a %2$s>dokumentasi</a>.','If you need to launch the Setup Wizard again, you can find it in the settings. Just enter "wizard" in the search field.'=>'Jika Anda perlu menjalankan Kode Pengaturan lagi, Anda dapat menemukannya di pengaturan. Cukup masukkan "wizard" di kolom pencarian.','Happy tagging!'=>'Selamat menandai!','Tag Groups Setup Wizard'=>'Kode Pengaturan Grup Tag','Now you are ready to create your own tag groups. If you prefer to start out from a sample, we will create for you three groups and three tags. You can play around with them, rename or delete them.'=>'Sekarang Anda siap untuk membuat grup tag Anda sendiri. Jika Anda lebih suka memulai dari contoh, kami akan membuatkan untuk Anda tiga grup dan tiga tag. Anda dapat bereksperimen dengan mereka, mengubah nama atau menghapusnya.','Create sample groups:'=>'Buat grup contoh:','Create sample tags in these groups:'=>'Buat tag contoh di grup ini:','Next Step'=>'Langkah Berikutnya','On the following pages we will guide you through the basic settings that you need for the most common features.'=>'Di halaman berikutnya, kami akan memandu Anda melalui pengaturan dasar yang Anda butuhkan untuk fitur-fitur yang paling umum.','You can later make changes or fine-tune the details in the Tag Groups settings.'=>'Anda dapat melakukan perubahan atau menyempurnakan detail di pengaturan Grup Tag nanti.','(show me the menu)'=>'(tunjukkan menu kepada saya)','Feel free to abort the Setup Wizard any time and continue on your own path. You can also launch it again at a later time.'=>'Jangan ragu untuk membatalkan Kode Pengaturan kapan saja dan melanjutkan dengan jalan Anda sendiri. Anda juga dapat menjalankannya lagi di lain waktu.','The wizard will offer more options after upgrading to premium.'=>'Kode akan menawarkan lebih banyak opsi setelah melakukan upgrade ke premium.','Choose the taxonomies for which you want to use tag groups.'=>'Pilih taxonomies yang ingin Anda gunakan untuk grup tag.','In most cases the default taxonomy <b>Tags (post_tag)</b> will do the job.'=>'Dalam banyak kasus, taxonomy default <b>Tags (post_tag)</b> akan melakukan pekerjaan dengan baik.','post type'=>'post type','You will find more options in the Tag Groups settings.'=>'Anda akan menemukan lebih banyak opsi di pengaturan Grup Tag.','Tag Group Administration'=>'Administrasi Grup Tag','Filter by label'=>'Filter berdasarkan label','Tag Group name'=>'Nama Grup Tag','Number of assigned tags'=>'Jumlah tag yang ditugaskan','Actions'=>'Tindakan','Change order'=>'Ubah urutan','Group ID'=>'ID Grup','Edit'=>'Edit','Create'=>'Buat','new'=>'baru','label'=>'label','Delete this group.'=>'Hapus grup ini.','Create a new group below.'=>'Buat grup baru di bawah.','Add New Tag Group'=>'Tambahkan Grup Tag Baru','move up'=>'pindahkan ke atas','move down'=>'pindahkan ke bawah','reload'=>'muat ulang','next page'=>'halaman berikutnya','previous page'=>'halaman sebelumnya','go to page:'=>'pergi ke halaman:','Show posts'=>'Tampilkan pos','Show tags'=>'Tampilkan tag','Do you really want to delete this tag group?'=>'Apakah Anda benar-benar ingin menghapus grup tag ini?','Please visit <a %1$s>%2$s</a>.'=>'Silakan kunjungi <a %1$s>%2$s</a>.','Read more'=>'Baca lebih lanjut','Thanks for using Tag Groups | %1$sTaxoPress.com%2$s | Version %3$s'=>'Terima kasih telah menggunakan Tag Groups | %1$sTaxoPress.com%2$s | Versi %3$s','Assign to'=>'Tetapkan ke','Filter off'=>'Filter mati','Please select one of the languages above to see the correct tag groups!'=>'Silakan pilih salah satu bahasa di atas untuk melihat grup tag yang benar!','Groups'=>'Grup']];